from itertools import product

def is_kawaii(seq):
    # seq is a sequence of integers from {1, 2, ..., M}
    # Condition: if k >= 2 is in seq, then k-1 is in seq AND first_pos(k-1) < last_pos(k)
    present = set(seq)
    for k in present:
        if k >= 2:
            if k-1 not in present:
                return False
            first_k_minus_1 = seq.index(k-1)
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if first_k_minus_1 >= last_k:
                return False
    return True

def count_kawaii(L, M):
    count = 0
    for seq in product(range(1, M + 1), repeat=L):
        if is_kawaii(seq):
            count += 1
    return count

# Test for small L and M
for L in range(1, 6):
    for M in range(1, 6):
        print(f"L={L}, M={M}: {count_kawaii(L, M)}")
